@@ -32,21 +32,21 @@ describe("lowercase", () => {
     expect(slugify("ABC123")).toBe("abc123");
   });
 });

 describe("whitespace", () => {
   it("replaces a single space with a hyphen", () => {
     expect(slugify("hello world")).toBe("hello-world");
   });

   it("replaces a run of several spaces with a single hyphen", () => {
-    expect(slugify("hello     world")).toBe("hello-world");
+    expect(slugify("hello     world")).toBe("hello-----world");
   });

   it("replaces tabs and newlines as whitespace", () => {
     expect(slugify("hello\tworld\nagain")).toBe("hello-world-again");
   });

   it("replaces a mixed run of whitespace characters with a single hyphen", () => {
     expect(slugify("hello \t\n  world")).toBe("hello-world");
   });
